create table marketing_post (id text primary key, revision integer not null default 1, content jsonb not null, scheduled_at timestamptz null, approved jsonb null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz null);
create index marketing_post_due on marketing_post (scheduled_at) where approved is not null and deleted_at is null;
create table marketing_media (id text primary key, value jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz null);
create table marketing_settings (id text primary key, revision integer not null default 1, value jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz null);
create table marketing_publication (id text primary key, post_id text not null references marketing_post(id), channel text not null, state text not null, value jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz null, unique(post_id, channel));
create table marketing_audit (id text primary key, actor text not null, action text not null, entity_id text not null, value jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz null);
